// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address user, uint8 extraCalls) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(user != address(0) && user != address(c));
        vm.assume(extraCalls >= 1 && extraCalls <= 5);
        vm.deal(user, amount * (extraCalls + 1));
        vm.startPrank(user);
        c.deposit{value: amount}();
        uint256 totalDeposited = amount;
        uint256 totalWithdrawn = 0;
        for (uint256 i = 0; i < extraCalls; i++) {
            uint256 balBefore = address(c).balance;
            c.withdrawAll();
            totalWithdrawn += balBefore - address(c).balance;
        }
        vm.stopPrank();
        assertTrue(totalWithdrawn <= totalDeposited);
    }
}
